const SOURCE='https://raw.githubusercontent.com/SubmitGame/awesome-decomp-games/main/';
const labels={'static-recomp':'RECOMPILAÇÃO','source-port':'PORT NATIVO','engine-remake':'RECRIAÇÃO DE ENGINE'};
const knownPorts=['HarbourMasters/Shipwright','HarbourMasters/2ship2harkinian','coop-deluxe/sm64coopdx','OpenGOAL/jak-project','HarbourMasters/Starship'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let games=[],limit=24,busy=false,favorites=new Set(),lastData=null;
let curated=typeof CURATED_PROJECTS!=="undefined"?CURATED_PROJECTS.map(g=>({...g})):[];
try{favorites=new Set(JSON.parse(localStorage.getItem('atlas-favorites')||'[]'))}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
function date(s){if(!s||!Number.isFinite(Date.parse(s)))return 'não informada';return new Date(s).toLocaleDateString('pt-BR')}
function platforms(g){return (g.platform||'Não informada').split(/\s*\/\s*/).map(s=>s.trim()).filter(Boolean)}
function normalized(data){if(!Array.isArray(data.games)||!data.generated_at)throw Error('Base inválida');return mergeCatalog(data).filter(g=>g.repo&&!/android|ios port/i.test(g.repo+" "+g.title)&&/^https:\/\/github\.com\/[^/]+\/[^/]+/.test(g.url)&& (labels[g.type]||knownPorts.some(r=>r.toLowerCase()===g.repo.toLowerCase()))).map(g=>({...g,type:labels[g.type]?g.type:'source-port'}))}
function mergeCatalog(data){
 const entries=new Map(data.games.filter(g=>typeof g.repo==='string').map(g=>[g.repo.toLowerCase(),g]));
 for(const extra of curated){
   const key=extra.repo.toLowerCase(),base=entries.get(key);
   const newerBase=base&&Date.parse(data.generated_at)>Date.parse(extra.verified_at);
   entries.set(key,{...(newerBase?{...extra,...base}:{...base,...extra}),id:extra.id,title:extra.title,platform:extra.platform,type:extra.type,cover:extra.cover,top_pick:extra.top_pick,verified_at:extra.verified_at,direct:true});
 }
 return [...entries.values()];
}
async function refreshCurated(){
 const results=await Promise.allSettled(curated.map(async g=>{
   const [repo,release]=await Promise.all([getJSON('https://api.github.com/repos/'+g.repo),getJSON('https://api.github.com/repos/'+g.repo+'/releases/latest')]);
   if(repo.full_name?.toLowerCase()!==g.repo.toLowerCase()||typeof release.tag_name!=='string'||!safeURL(release.html_url))throw Error('Resposta inválida');
   return {...g,stars:repo.stargazers_count,last_commit:repo.pushed_at,archived:repo.archived,release:release.tag_name,release_date:release.published_at,release_url:release.html_url,verified_at:new Date().toISOString()};
 }));
 let successes=0;
 results.forEach((r,i)=>{if(r.status==='fulfilled'){curated[i]=r.value;successes++}});
 if(successes){try{localStorage.setItem('replay-curated',JSON.stringify(curated))}catch{}}
 const status=$('#directStatus');if(status)status.textContent=successes===curated.length?'Projetos complementares: GitHub consultado agora.':'Projetos complementares: consulta indisponível; dados da última verificação.';
 if(lastData){games=normalized(lastData);$('#total').textContent=games.length.toLocaleString('pt-BR');makeFilters();render()}
}
function cover(g){if(g.cover&&/^covers\/[\w-]+\.png$/.test(g.cover))return g.cover;const t=g.title.toLowerCase();if(t.includes('ocarina of time')&&!t.includes('3d'))return 'covers/zelda.png';if(t.includes("majora")&&!t.includes('3d'))return 'covers/majora.png';if(t.includes('super mario 64')&&!t.includes('ds'))return 'covers/mario.png';if(t.includes('star fox 64'))return 'covers/starfox.png';return ''}
function picture(g){return cover(g)||(g.screenshot&&/^[\w/-]+\.(jpg|png|webp)$/.test(g.screenshot)?SOURCE+g.screenshot:'')||safeURL(g.thumb_src)||safeURL(g.og_image)}
function makeFilters(){const checked=new Set($$('input[name=platform]:checked').map(e=>e.value));const counts={};games.forEach(g=>platforms(g).forEach(p=>counts[p]=(counts[p]||0)+1));$('#platformTotal').textContent=Object.keys(counts).length;$('#platforms').innerHTML=Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([p,n])=>`<label><input name="platform" type="checkbox" value="${esc(p)}" ${checked.has(p)?'checked':''}> ${esc(p)} <small>${n}</small></label>`).join('')}
function filtered(){const q=$('#search').value.trim().toLowerCase(),ps=$$('input[name=platform]:checked').map(e=>e.value),ts=$$('input[name=type]:checked').map(e=>e.value);return games.filter(g=>(!q||`${g.title} ${g.repo} ${g.description||''}`.toLowerCase().includes(q))&&(!ps.length||platforms(g).some(p=>ps.includes(p)))&&(!ts.length||ts.includes(g.type))&&(!$('#released').checked||g.release)&&(!$('#favorites').checked||favorites.has(g.id))).sort((a,b)=>{switch($('#sort').value){case'name':return a.title.localeCompare(b.title,'pt-BR');case'updated':return (Date.parse(b.last_commit)||0)-(Date.parse(a.last_commit)||0);case'stars':return (b.stars||0)-(a.stars||0);default:return (a.top_pick||99999)-(b.top_pick||99999)||(b.stars||0)-(a.stars||0)}})}
function render(){const all=filtered();$('#resultCount').innerHTML=`<b>${all.length.toLocaleString('pt-BR')}</b> projetos encontrados`;$('#savedCount').textContent=favorites.size;$('#empty').hidden=all.length>0;$('#more').hidden=all.length<=limit;$('#grid').innerHTML=all.slice(0,limit).map(g=>{const img=picture(g);return `<article class="card"><div class="card-art"><span class="image-fallback" ${img?'hidden':''}>${esc(g.title.substring(0,2).toUpperCase())}</span>${img?`<img src="${esc(img)}" alt="${cover(g)?'Capa':'Imagem do projeto'}: ${esc(g.title)}" class="${cover(g)?'box':''}" loading="lazy">`:''}<span class="platform-badge">${esc(g.platform||'Plataforma não informada')}</span><button class="favorite" data-id="${esc(g.id)}" aria-label="${favorites.has(g.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(g.title)}" aria-pressed="${favorites.has(g.id)}">${favorites.has(g.id)?'♥':'♡'}</button></div><div class="card-body"><span class="type-tag ${g.type==='source-port'?'port':g.type==='engine-remake'?'engine':''}">${labels[g.type]}</span><h3><a class="project-title" href="${esc(safeURL(g.url))}" target="_blank" rel="noopener noreferrer">${esc(g.title)}</a></h3><div class="repo" title="${esc(g.repo)}">${esc(g.repo)}</div><div class="card-meta"><span class="release" title="${esc(g.release||'Sem release identificada')}">${g.archived?'◌ Arquivado':g.release?'● '+esc(g.release):'◌ Sem release'}</span><span>☆ ${Number(g.stars||0).toLocaleString('pt-BR',{notation:'compact'})}</span></div><div class="card-links"><a class="github" href="${esc(safeURL(g.url))}" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a class="details" href="${esc(safeURL(g.release_url)||safeURL(g.url)+'/releases')}" target="_blank" rel="noopener noreferrer">Releases ↗</a></div><div class="repo" style="margin-top:12px">Última atividade: ${date(g.last_commit)}</div>${g.direct?`<div class="direct-source">GitHub oficial · verificado em ${date(g.verified_at)}</div>`:""}</div></article>`}).join('');$$('.card-art img').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.previousElementSibling.hidden=false},{once:true}))}
function apply(data,label){lastData=data;games=normalized(data);$('#total').textContent=games.length.toLocaleString('pt-BR');makeFilters();render();$('#syncLabel').textContent=label;$('#syncDate').textContent='Dados da fonte: '+date(data.generated_at)}
async function getJSON(url){const r=await fetch(url,{cache:'no-cache',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('Fonte indisponível');return r.json()}
async function refresh(){if(busy)return;busy=true;$('#refresh').disabled=true;$('#syncLabel').textContent='Consultando atualizações…';const directTask=refreshCurated();try{const data=await getJSON(SOURCE+'data/games.json');normalized(data);apply(data,'Sincronizado com a base');try{localStorage.setItem('atlas-catalog',JSON.stringify(data))}catch{}}catch{if(games.length){$('#syncLabel').textContent='Sem conexão com a fonte';$('#syncDate').textContent+=' · cópia disponível'}else{$('#resultCount').textContent='Não foi possível carregar o catálogo. Tente atualizar.'}}finally{await directTask;busy=false;$('#refresh').disabled=false}}
function reset(){ $$('aside input').forEach(e=>e.checked=false);$('#search').value='';$('#sort').value='featured';limit=24;render()}
async function init(){try{const saved=JSON.parse(localStorage.getItem('replay-curated')||'[]');curated=curated.map(g=>{const cached=saved.find(s=>s.repo===g.repo);return cached&&Date.parse(cached.verified_at)>Date.parse(g.verified_at)?{...g,stars:cached.stars,last_commit:cached.last_commit,archived:cached.archived,release:cached.release,release_date:cached.release_date,release_url:cached.release_url,verified_at:cached.verified_at}:g})}catch{}let data;try{data=JSON.parse(localStorage.getItem('atlas-catalog')||'null');if(data)normalized(data)}catch{data=null}try{const bundled=await getJSON('catalog.json');if(!data||Date.parse(bundled.generated_at)>Date.parse(data.generated_at))data=bundled}catch{}if(data)apply(data,'Cópia disponível • buscando atualizações');await refresh()}
$('#search').addEventListener('input',()=>{limit=24;render()});$('aside').addEventListener('change',()=>{limit=24;render()});$('#sort').addEventListener('change',()=>{limit=24;render()});$('#clear').onclick=reset;$('#resetEmpty').onclick=reset;$('#more').onclick=()=>{limit+=24;render()};$('#refresh').onclick=refresh;
$('#grid').addEventListener('click',e=>{const b=e.target.closest('.favorite');if(!b)return;favorites.has(b.dataset.id)?favorites.delete(b.dataset.id):favorites.add(b.dataset.id);try{localStorage.setItem('atlas-favorites',JSON.stringify([...favorites]))}catch{$('#toast').textContent='Favoritos disponíveis apenas nesta sessão.';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}render()});
$('#savedNav').onclick=()=>{$('#favorites').checked=!$('#favorites').checked;limit=24;render();$('#catalogo').scrollIntoView({behavior:'smooth'})};['#aboutBtn','#sourcesBtn','#footerAbout'].forEach(s=>$(s).onclick=()=>$('#about').showModal());$('.close').onclick=()=>$('#about').close();$('#about').addEventListener('click',e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#about').open){e.preventDefault();$('#search').focus()}});setInterval(()=>{if(!document.hidden)refresh()},30*60*1000);init();
